scripts.script:
local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/xHeptc/Kavo-UI-Library/main/source.lua"))()
local Window = Library.CreateLib("Rags to Richest", "DarkTheme")

local MainTab = Window:NewTab("Main Farm")
local MainSection = MainTab:NewSection("Money")

MainSection:NewButton("AutoClicker here for money", "auto click dosent work on this game", function()
    local args = {
        [1] = "roll"
    }

    game:GetService("ReplicatedStorage").Signal.Money:InvokeServer(unpack(args))  
end)
